78	    public static Corpus Cargar(string dataDir)
79	    {
80	        var c = new Corpus();
81	        foreach (var f in Directory.GetFiles(Path.Combine(dataDir, "reglamento"), "*.md"))
82	        {
83	            var doc = Path.GetFileName(f);
84	            foreach (var l in File.ReadLines(f))
85	            {
86	                if (l.StartsWith("## ", StringComparison.Ordinal))
87	                    c.Citas.Add((doc, l[3..].Trim()));
88	            }
89	        }
90	        foreach (var f in Directory.GetFiles(Path.Combine(dataDir, "api"), "*.json"))
91	        {
92	            using var d = JsonDocument.Parse(File.ReadAllText(f));
93	            if (d.RootElement.ValueKind != JsonValueKind.Array) continue;
94	            foreach (var e in d.RootElement.EnumerateArray())
95	            {
96	                if (e.ValueKind != JsonValueKind.Object) continue;
97	                if (!e.TryGetProperty("id", out var id) || !e.TryGetProperty("nombre", out var nom)
98	                    || !e.TryGetProperty("programa", out var prog)) continue;
99	                var p = new Persona(id.GetString() ?? "", nom.GetString() ?? "", prog.GetString() ?? "");
100	                // Los estudiantes se distinguen de los coordinadores por tener semestre.
101	                if (e.TryGetProperty("semestre", out _)) c.Estudiantes.Add(p); else c.Coordinadores.Add(p);
102	            }
103	        }
104	        return c;
105	    }
