5	// Raíz del repositorio y carpeta de datos, localizadas subiendo desde el directorio de trabajo.
6	static string? Subir(Func<string, bool> ok)
7	{
8	    for (var d = new DirectoryInfo(Directory.GetCurrentDirectory()); d != null; d = d.Parent)
9	        if (ok(d.FullName)) return d.FullName;
10	    return null;
11	}
12	
13	var dataDir = Environment.GetEnvironmentVariable("EVALS_DATA");
14	var raiz = Subir(d => File.Exists(Path.Combine(d, "TutorFlow.sln")));
15	if (string.IsNullOrEmpty(dataDir))
16	{
17	    var padre = Subir(d => Directory.Exists(Path.Combine(d, "data", "reglamento")));
18	    dataDir = padre is null ? null : Path.Combine(padre, "data");
19	}
20	if (dataDir is null || !Directory.Exists(dataDir))
21	{
22	    Console.Error.WriteLine("No se encontró la carpeta de datos (use EVALS_DATA).");
23	    return 2;
24	}
25	var evalsDir = raiz is null ? Path.Combine(Directory.GetCurrentDirectory(), "evals") : Path.Combine(raiz, "evals");
26	
27	var url = (Environment.GetEnvironmentVariable("EVALS_API_URL") is { Length: > 0 } u ? u : "http://localhost:8080").TrimEnd('/');
28	var pausaMs = int.TryParse(Environment.GetEnvironmentVariable("EVALS_PAUSA_MS"), out var pm) ? pm : 1500;
29	var esperaMs = int.TryParse(Environment.GetEnvironmentVariable("EVALS_ESPERA_MS"), out var em) ? em : 2000;
30	const int Reintentos = 3;
31	var llave = Environment.GetEnvironmentVariable("LLM_API_KEY"); // solo para R2; no se envía a ningún lado
32	
33	var casos = new List<Caso>();
34	void CargarCasos(string ruta)
35	{
36	    var lista = JsonSerializer.Deserialize<List<Caso>>(File.ReadAllText(ruta), Evaluador.JsonOpts);
37	    if (lista != null) casos.AddRange(lista);
38	}
39	CargarCasos(Path.Combine(dataDir, "preguntas-ejemplo.json"));
40	var extra = Path.Combine(evalsDir, "casos-adicionales.json");
41	if (File.Exists(extra)) CargarCasos(extra);
42	
43	var corpus = Corpus.Cargar(dataDir);
44	using var http = new HttpClient { Timeout = TimeSpan.FromSeconds(120) };
45	var resultados = new List<ResultadoCaso>();
46	
47	Console.WriteLine($"Evals contra {url}: {casos.Count} casos");
48	for (var i = 0; i < casos.Count; i++)
49	{
50	    var caso = casos[i];
51	    if (i > 0 && pausaMs > 0) await Task.Delay(pausaMs);
52	    var cuerpoPeticion = JsonSerializer.Serialize(new
53	    {
54	        pregunta = caso.Pregunta,
55	        usuario = new { rol = caso.Usuario.Rol, id = caso.Usuario.Id },
56	    });
57	    RespuestaHttp? resp = null;
58	    var motivoFinal = "";
59	    for (var intento = 0; intento <= Reintentos; intento++)
60	    {
61	        if (intento > 0) await Task.Delay(esperaMs * (1 << (intento - 1)));
62	        try
63	        {
64	            using var content = new StringContent(cuerpoPeticion, Encoding.UTF8, "application/json");
65	            using var hr = await http.PostAsync(url + "/api/asistente/preguntar", content);
66	            var texto = await hr.Content.ReadAsStringAsync();
67	            var codigo = (int)hr.StatusCode;
68	            if (codigo is 503 or 429) { motivoFinal = $"proveedor sin respuesta ({codigo})"; continue; }
69	            resp = new RespuestaHttp(codigo, texto);
70	            break;
71	        }
72	        catch (Exception ex) when (ex is HttpRequestException or TaskCanceledException)
73	        {
74	            motivoFinal = "error de red: " + ex.GetType().Name;
75	        }
76	    }
77	    var res = resp is null ? Evaluador.SinResultado(caso, motivoFinal) : Evaluador.Evaluar(caso, resp, corpus, llave);
78	    resultados.Add(res);
79	    var estado = res.Estado switch { Estado.Ok => "OK", Estado.Falla => "FALLA", _ => "SIN RESULTADO" };
80	    Console.WriteLine($"{res.Id,-8} {res.Escenario,-10} {estado,-13} {string.Join("; ", res.Motivos)}");
81	}
82	
83	var resumen = Evaluador.Resumir(resultados);
84	var veredicto = resumen.CodigoSalida switch { 0 => "APROBADA", 1 => "REPROBADA", _ => "INCONCLUSA" };
85	Console.WriteLine();
86	Console.WriteLine($"Aprobadas: {resumen.Aprobadas}/{resumen.ConResultado} con resultado ({resumen.Total} casos, {resumen.SinResultado} sin resultado)");
87	Console.WriteLine($"Puntaje: {resumen.Puntaje:P1} (umbral {resumen.Umbral:P0})");
88	Console.WriteLine($"Reglas duras (R1 citas, R2 privacidad/llave): {(resumen.ReglasDurasOk ? "OK" : "VIOLADAS")}");
89	Console.WriteLine($"Tokens: total {resumen.TokensTotales}, promedio {resumen.TokensPromedio:F1} por pregunta");
90	Console.WriteLine($"Costo USD: total {resumen.CostoTotalUsd:F6}, promedio {resumen.CostoPromedioUsd:F6}, estimado por 1.000 preguntas {resumen.CostoPor1000Usd:F4}");
91	Console.WriteLine($"Veredicto: {veredicto}");
92	
93	Directory.CreateDirectory(Path.Combine(evalsDir, "resultados"));
94	File.WriteAllText(Path.Combine(evalsDir, "resultados", "ultimo.json"),
95	    JsonSerializer.Serialize(new { fecha = DateTime.UtcNow, veredicto, resumen, casos = resultados },
96	        new JsonSerializerOptions { WriteIndented = true, PropertyNamingPolicy = JsonNamingPolicy.CamelCase }));
97	return resumen.CodigoSalida;
