13	/// <summary>Manejador HTTP falso que decide la respuesta con una función y registra las peticiones. Sin red.</summary>
14	public sealed class ProveedorFuncion(Func<PeticionRegistrada, int, HttpResponseMessage> f) : HttpMessageHandler
15	{
16	    public List<PeticionRegistrada> Peticiones { get; } = [];
17	
18	    protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken ct)
19	    {
20	        var cab = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
21	        foreach (var h in request.Headers) cab[h.Key] = string.Join(",", h.Value);
22	        var cuerpo = request.Content == null ? "" : await request.Content.ReadAsStringAsync(ct);
23	        var reg = new PeticionRegistrada(request.Method.Method, request.RequestUri!.ToString(), cab, cuerpo);
24	        int n;
25	        lock (Peticiones) { Peticiones.Add(reg); n = Peticiones.Count; }
26	        return f(reg, n);
27	    }
28	}
