84	/// <summary>
85	/// T6c: compatibilidad con Gemini 3 vía formato OpenAI. Cada tool_call puede traer extra_content con la
86	/// thought_signature (opaca) y debe reenviarse sin cambios en el mensaje assistant de la vuelta siguiente.
87	/// Diseño asumido para extra_content malformado o no objeto (pruebas T6c_7): no hay 500; se acepta 200 (se ignora)
88	/// o 503, y en el caso 200 nada que no sea un objeto JSON se reenvía como extra_content.
89	/// </summary>
90	public class Gemini3CompatTests
91	{
92	    private const string Cita = "{\"documento\":\"reglamento-prueba.md\",\"seccion\":\"Nota mínima\"}";
93	    private const string FinalJson = "{\"respuesta\":\"La nota mínima es 3.0.\",\"citas\":[" + Cita + "]}";
94	
95	    // Firma opaca con barras, mas, igual, comillas, contrabarra, saltos de linea y unicode.
96	    private const string FirmaEspecial = "Ci4Bjz1r/X+a==\"q\\x\\\\y\n\t/áñ\U0001F600==";
97	
98	    private static JsonObject Extra(string firma) =>
99	        new() { ["google"] = new JsonObject { ["thought_signature"] = firma } };
100	
101	    private static string Final(int entrada = 5, int salida = 2) => new JsonObject
102	    {
103	        ["choices"] = new JsonArray(new JsonObject
104	        {
105	            ["message"] = new JsonObject { ["role"] = "assistant", ["content"] = FinalJson },
106	            ["finish_reason"] = "stop",
107	        }),
108	        ["usage"] = new JsonObject { ["prompt_tokens"] = entrada, ["completion_tokens"] = salida },
109	    }.ToJsonString();
110	
111	    /// <summary>Respuesta con tool_calls; cada llamada es (id, nombre, args, extra_content o null).</summary>
112	    private static string ConLlamadas(params (string Id, string Nombre, string Args, JsonNode? Extra)[] ll) => new JsonObject
113	    {
114	        ["choices"] = new JsonArray(new JsonObject
115	        {
116	            ["message"] = new JsonObject
117	            {
118	                ["role"] = "assistant",
119	                ["content"] = null,
120	                ["tool_calls"] = new JsonArray(ll.Select(l =>
121	                {
122	                    var o = new JsonObject
123	                    {
124	                        ["id"] = l.Id,
125	                        ["type"] = "function",
126	                        ["function"] = new JsonObject { ["name"] = l.Nombre, ["arguments"] = l.Args },
127	                    };
128	                    if (l.Extra != null) o["extra_content"] = l.Extra;
129	                    return (JsonNode)o;
130	                }).ToArray()),
131	            },
132	            ["finish_reason"] = "tool_calls",
133	        }),
134	        ["usage"] = new JsonObject { ["prompt_tokens"] = 10, ["completion_tokens"] = 1 },
135	    }.ToJsonString();
