137	    /// <summary>Variante con el cuerpo crudo del tool_call (permite extra_content con JSON arbitrario, p. ej. no objeto).</summary>
138	    private static string ConLlamadaCruda(string extraCrudo) =>
139	        "{\"choices\":[{\"message\":{\"role\":\"assistant\",\"content\":null,\"tool_calls\":[{\"id\":\"c1\",\"type\":\"function\"," +
140	        "\"function\":{\"name\":\"consultar_notas\",\"arguments\":\"{\\\"estudianteId\\\":\\\"T-E1\\\"}\"},\"extra_content\":" + extraCrudo +
141	        "}]},\"finish_reason\":\"tool_calls\"}],\"usage\":{\"prompt_tokens\":10,\"completion_tokens\":1}}";
142	
143	    private static ProveedorFuncion Guion(params string[] respuestas) => new((_, n) =>
144	        n <= respuestas.Length
145	            ? new HttpResponseMessage(HttpStatusCode.OK) { Content = new StringContent(respuestas[n - 1], Encoding.UTF8, "application/json") }
146	            : throw new InvalidOperationException("Guion agotado"));
147	
148	    private static JsonArray LlamadasAssistant(PeticionRegistrada p)
149	    {
150	        var msgs = p.Json["messages"]!.AsArray();
151	        var asistente = msgs.Last(m => (string?)m!["role"] == "assistant" && m["tool_calls"] != null)!;
152	        return asistente["tool_calls"]!.AsArray();
153	    }
