301	    /// <summary>Imita a Google: 400 si algún tool_call firmado en el historial pierde su extra_content (o lo altera).</summary>
302	    private static ProveedorFuncion ProveedorQueExigeFirma(params bool[] firmadas)
303	    {
304	        string[] nombres = ["consultar_notas", "consultar_asistencia"];
305	        return new ProveedorFuncion((p, n) =>
306	        {
307	            if (n == 1)
308	            {
309	                var ll = firmadas.Select((f, i) => ($"id{i}", nombres[i % 2], "{\"estudianteId\":\"T-E1\"}",
310	                    f ? (JsonNode?)Extra("SIG-" + i + "/+==") : null)).ToArray();
311	                return Ok(ConLlamadas(ll));
312	            }
313	            var asistente = p.Json["messages"]!.AsArray().Last(m => (string?)m!["role"] == "assistant" && m["tool_calls"] != null)!;
314	            var calls = asistente["tool_calls"]!.AsArray();
315	            for (var i = 0; i < firmadas.Length; i++)
316	            {
317	                var ok = i < calls.Count && (firmadas[i]
318	                    ? JsonNode.DeepEquals(calls[i]!["extra_content"], Extra("SIG-" + i + "/+=="))
319	                    : calls[i]!["extra_content"] == null);
320	                if (!ok)
321	                    return new HttpResponseMessage(HttpStatusCode.BadRequest)
322	                    { Content = new StringContent("{\"error\":{\"message\":\"Function call is missing a thought_signature\"}}", Encoding.UTF8, "application/json") };
323	            }
324	            return Ok(Final());
325	        });
326	    }
