30	/// <summary>API con adaptadores reales, un manejador HTTP arbitrario, auditoría temporal y logs en memoria.</summary>
31	public sealed class EntornoT6c : IDisposable
32	{
33	    public const string Url = "/api/asistente/preguntar";
34	    private readonly WebApplicationFactory<Program> _fabrica;
35	    public string RutaAuditoria { get; } = Path.Combine(Path.GetTempPath(), "tf-t6c-" + Guid.NewGuid().ToString("N") + ".jsonl");
36	    public LogsEnMemoria Logs { get; } = new();
37	    public HttpClient Cliente { get; }
38	
39	    public EntornoT6c(HttpMessageHandler proveedor, string? proveedorLlm = null, string? modelo = null, string? baseUrl = null)
40	    {
41	        var cfg = new Dictionary<string, string?>
42	        {
43	            ["Datos:Ruta"] = Fabrica.RutaFixtures,
44	            ["LLM_API_KEY"] = "llave-t6c-no-secreta-real",
45	            ["Auditoria:Ruta"] = RutaAuditoria,
46	        };
47	        if (proveedorLlm != null) cfg["LLM_PROVIDER"] = proveedorLlm;
48	        if (modelo != null) cfg["LLM_MODEL"] = modelo;
49	        if (baseUrl != null) cfg["LLM_BASE_URL"] = baseUrl;
50	        _fabrica = new WebApplicationFactory<Program>().WithWebHostBuilder(b =>
51	        {
52	            foreach (var (k, v) in cfg) b.UseSetting(k, v);
53	            b.ConfigureAppConfiguration((_, c) => c.AddInMemoryCollection(cfg));
54	            b.ConfigureServices(sv => sv.AddLogging(l => { l.SetMinimumLevel(LogLevel.Trace); l.AddProvider(Logs); }));
55	            b.ConfigureTestServices(sv => sv.AddHttpClient("llm").ConfigurePrimaryHttpMessageHandler(() => proveedor));
56	        });
57	        Cliente = _fabrica.CreateClient();
58	        Cliente.Timeout = TimeSpan.FromSeconds(60);
59	    }
60	
61	    public async Task<(HttpStatusCode Codigo, string Cuerpo)> Preguntar(string pregunta, string rol = "estudiante", string id = "T-E1")
62	    {
63	        var json = JsonSerializer.Serialize(new { pregunta, usuario = new { rol, id } });
64	        var r = await Cliente.PostAsync(Url, new StringContent(json, Encoding.UTF8, "application/json"));
65	        return (r.StatusCode, await r.Content.ReadAsStringAsync());
66	    }
67	
68	    public string TextoAuditoria()
69	    {
70	        if (!File.Exists(RutaAuditoria)) return "";
71	        using var fs = new FileStream(RutaAuditoria, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete);
72	        using var sr = new StreamReader(fs, Encoding.UTF8);
73	        return sr.ReadToEnd();
74	    }
75	
76	    public void Dispose()
77	    {
78	        Cliente.Dispose();
79	        _fabrica.Dispose();
80	        try { if (File.Exists(RutaAuditoria)) File.Delete(RutaAuditoria); } catch { }
81	    }
82	}
