95	    // Firma opaca con barras, mas, igual, comillas, contrabarra, saltos de linea y unicode.
96	    private const string FirmaEspecial = "Ci4Bjz1r/X+a==\"q\\x\\\\y\n\t/áñ\U0001F600==";
97	
98	    private static JsonObject Extra(string firma) =>
99	        new() { ["google"] = new JsonObject { ["thought_signature"] = firma } };
100	
101	    private static string Final(int entrada = 5, int salida = 2) => new JsonObject
102	    {
103	        ["choices"] = new JsonArray(new JsonObject
104	        {
105	            ["message"] = new JsonObject { ["role"] = "assistant", ["content"] = FinalJson },
106	            ["finish_reason"] = "stop",
107	        }),
108	        ["usage"] = new JsonObject { ["prompt_tokens"] = entrada, ["completion_tokens"] = salida },
109	    }.ToJsonString();
