143	    private static ProveedorFuncion Guion(params string[] respuestas) => new((_, n) =>
144	        n <= respuestas.Length
145	            ? new HttpResponseMessage(HttpStatusCode.OK) { Content = new StringContent(respuestas[n - 1], Encoding.UTF8, "application/json") }
146	            : throw new InvalidOperationException("Guion agotado"));
